+  router.get('/books', ({ query }) => {
+    const total = inventory.list().length
+    // default params
+    const pageRaw = query.get('page')
+    const limitRaw = query.get('limit')
+
+    let page = 1
+    let limit = 20
+
+    if (pageRaw !== null && pageRaw !== undefined) {
+      const n = Number(pageRaw)
+      if (Number.isNaN(n)) return { status: 400, body: { error: 'Invalid query' } }
+      page = n
+    }
+    if (limitRaw !== null && limitRaw !== undefined) {
+      const n = Number(limitRaw)
+      if (Number.isNaN(n)) return { status: 400, body: { error: 'Invalid query' } }
+      limit = n
+    }
+
+    // validation
+    if (page < 1 || limit < 1) {
+      return { status: 400, body: { error: 'Invalid query' } }
+    }
+
+    // clamp limit
+    if (limit > 50) limit = 50
+
+    const books = inventory.list()
+    const start = (page - 1) * limit
+    const end = start + limit
+    const pageItems = books.slice(start, end)
+    return { status: 200, body: pageItems, headers: { 'X-Total-Count': String(total) } }
+  })

